# 学生成绩管理系统
scores = []  # 存储成绩的列表

print("=" * 40)
print("      学生成绩管理系统 v1.0")
print("=" * 40)

while True:
    print("\n功能菜单：")
    print("1. 添加成绩")
    print("2. 显示所有成绩")
    print("3. 统计分析（平均分/最高/最低）")
    print("4. 排序（从高到低）")
    print("5. 查找成绩")
    print("6. 删除成绩")
    print("7. 退出系统")

    choice = input("\n请输入你的选择（1-7）：")

    if choice == "1":
        # 添加成绩
        while True:
            score_str = input("请输入成绩（输入q返回）：")
            if score_str.lower() == 'q':
                break
            if not score_str.isdigit():
                print("请输入有效的数字！")
                continue
            score = int(score_str)
            if score < 0 or score > 100:
                print("成绩要在0-100之间！")
                continue
            scores.append(score)
            print(f"已添加成绩：{score}")

    elif choice == "2":
        # 显示所有成绩
        if len(scores) == 0:
            print("还没有成绩呢！")
        else:
            print(f"共有 {len(scores)} 个成绩：")
            for i, score in enumerate(scores, 1):
                print(f"  {i}. {score}分")

    elif choice == "3":
        # 统计分析
        if len(scores) == 0:
            print("还没有成绩呢！")
        else:
            avg = sum(scores) / len(scores)
            max_s = max(scores)
            min_s = min(scores)
            print(f"统计结果：")
            print(f"  总人数：{len(scores)}人")
            print(f"  平均分：{avg:.2f}分")
            print(f"  最高分：{max_s}分")
            print(f"  最低分：{min_s}分")

    elif choice == "4":
        # 排序
        if len(scores) == 0:
            print("还没有成绩呢！")
        else:
            scores.sort(reverse=True)
            print("已按从高到低排序：")
            for i, score in enumerate(scores, 1):
                print(f"  第{i}名：{score}分")

    elif choice == "5":
        # 查找
        if len(scores) == 0:
            print("还没有成绩呢！")
        else:
            target = int(input("请输入要查找的分数："))
            count = scores.count(target)
            if count > 0:
                print(f"找到 {count} 个 {target} 分")
                indexes = [i for i, s in enumerate(scores) if s == target]
                print("位置：", [i+1 for i in indexes])
            else:
                print(f"没有找到 {target} 分")

    elif choice == "6":
        # 删除
        if len(scores) == 0:
            print("还没有成绩呢！")
        else:
            print("当前成绩列表：")
            for i, score in enumerate(scores, 1):
                print(f"  {i}. {score}分")
            idx = int(input("请输入要删除的序号："))
            if 1 <= idx <= len(scores):
                removed = scores.pop(idx - 1)
                print(f"已删除第{idx}个成绩：{removed}分")
            else:
                print("序号错误！")

    elif choice == "7":
        print("感谢使用，再见！")
        break

    else:
        print("输入有误，请输入1-7之间的数字！")

class Student:
    def __init__(self, name, student_id):
        self.name = name
        self.student_id = student_id
        self.scores = {}  # 字典：科目 -> 分数

    # 添加分数
    def add_score(self, subject, score):
        self.scores[subject] = score

    # 计算平均分
    def get_average(self):
        if not self.scores:
            return 0
        return sum(self.scores.values()) / len(self.scores)

    # 获取等级
    def get_grade(self, subject):
        if subject not in self.scores:
            return "没有这科成绩"
        score = self.scores[subject]
        if score >= 90:
            return "A"
        elif score >= 80:
            return "B"
        elif score >= 60:
            return "C"
        else:
            return "D"

    # 打印成绩单
    def print_report(self):
        print(f"===== {self.name}的成绩单 =====")
        print(f"学号：{self.student_id}")
        for subject, score in self.scores.items():
            grade = self.get_grade(subject)
            print(f"{subject}: {score}分 ({grade})")
        print(f"平均分：{self.get_average():.1f}分")
        print("==============================")

# 使用
