TODO_FILE = "my_todos.txt"

def load_todos():
    """从文件加载待办列表"""
    todos = []
    try:
        with open(TODO_FILE, "r", encoding="utf-8") as f:
            for line in f:
                todo = line.strip()
                if todo:  # 跳过空行
                    todos.append(todo)
    except FileNotFoundError:
        # 文件不存在就返回空列表
        pass
    return todos

def save_todos(todos):
    """把待办列表保存到文件"""
    with open(TODO_FILE, "w", encoding="utf-8") as f:
        for todo in todos:
            f.write(todo + "\n")

def show_todos(todos):
    if not todos:
        print("暂无待办事项～")
        return
    print("===== 待办事项 =====")
    for i, todo in enumerate(todos, 1):
        print(f"{i}. {todo}")
    print(f"共 {len(todos)} 项")

def main():
    todos = load_todos()
    print(f"已加载 {len(todos)} 条待办")

    while True:
        print("\n===== 待办菜单 =====")
        print("1. 查看待办")
        print("2. 添加待办")
        print("3. 删除待办")
        print("4. 退出")
        choice = input("请选择：")

        if choice == "1":
            show_todos(todos)
        elif choice == "2":
            todo = input("输入待办内容：")
            if todo:
                todos.append(todo)
                save_todos(todos)
                print("添加成功！")
        elif choice == "3":
            show_todos(todos)
            if todos:
                num = int(input("要删除第几项？"))
                if 1 <= num <= len(todos):
                    deleted = todos.pop(num - 1)
                    save_todos(todos)
                    print(f"已删除：{deleted}")
                else:
                    print("编号不对")
        elif choice == "4":
            print("再见！")
            break
        else:
            print("无效选择")

if __name__ == "__main__":
    main()
